ver for each attempt\n const server = createServer();\n \n server.once('error', (err) => {\n if (err.code === 'EADDRINUSE') {\n console.log(`Port ${PORT} is in use. Trying next port...`);\n currentPortIndex++;\n startServerWithPreferredPorts(); // Try the next port\n } else {\n console.error(`Server error: ${err.message}`);\n process.exit(1);\n }\n });\n \n server.listen(PORT, () => {\n console.log(`Enhanced server (with Alpha Vantage and Mistral integration) is running at http://localhost:${PORT}/`);\n if (ALPHA_VANTAGE_API_KEY === 'YOUR_API_KEY_HERE') {\n console.warn('***********************************************************************************');\n console.warn('WARNING: Alpha Vantage API key is not set in src/enhanced-server.js.');\n console.warn('Data for new companies will be very limited. Get a free key from Alpha Vantage.');\n console.warn('***********************************************************************************');\n }\n });\n}\n\n// Start the server with the preferred ports\nstartServerWithPreferredPorts();\n@@ ... @@\n// Start server on the first available port\nfunction startServer() {\n // Try each port in sequence\n function tryPort(portIndex) {\n if (portIndex >= PORTS_TO_TRY.length) {\n console.error(\"All ports in use. Cannot start the server.\");\n process.exit(1);\n return;\n }\n\n const port = PORTS_TO_TRY[portIndex];\n const server = createAndStartServer();\n \n // Set up error handler before attempting to listen\n server.on('error', (err) => {\n if (err.code === 'EADDRINUSE') {\n console.log(`Port ${port} is in use. Trying next port...`);\n tryPort(portIndex + 1); // Try next port in the list\n } else {\n console.error(`Error starting server: ${err.message}`);\n process.exit(1);\n }\n });\n\n // Try to start the server\n console.log(`Attempting to start server on port ${port}...`);\n server.listen(port, () => {\n PORT = port; // Update the PORT variable\n console.log(`Enhanced server (with Alpha Vantage and Mistral integration)