 userMetricsComparison,
 chartData
 };
}

function compareMetric(value1, value2, id1, id2) {
 if ((value1 === null || value1 === undefined) && (value2 === null || value2 === undefined)) {
 return {better: null, differencePercent: 0, value1: value1, value2: value2};
 }
 if (value1 === null || value1 === undefined) {
 return {better: id2, differencePercent: 100, value1: value1, value2: value2};
 }
 if (value2 === null || value2 === undefined) {
 return {better: id1, differencePercent: 100, value1: value1, value2: value2};
 }
 const better = parseFloat(value1) > parseFloat(value2) ? id1 : id2;
 const max = Math.max(Math.abs(parseFloat(value1)), Math.abs(parseFloat(value2)));
 const differencePercent = max === 0 ? 0 : Math.abs((parseFloat(value1) - parseFloat(value2)) / max) * 100;
 return {
 better,
 differencePercent: parseFloat(differencePercent.toFixed(2)),
 value1: parseFloat(value1),
 value2: parseFloat(value2)
 };
}

function parseQuery(reqUrl) {
 const parsedUrl = url.parse(reqUrl, true);
 return parsedUrl.query;
}

function formatNumber(num) {
 if (num === null || num === undefined) return 'N/A';
 if (Math.abs(num) >= 1e12) return (num / 1e12).toFixed(2) + ' T';
 if (Math.abs(num) >= 1e9) return (num / 1e9).toFixed(2) + ' B';
 if (Math.abs(num) >= 1e6) return (num / 1e6).toFixed(2) + ' M';
 if (Number.isInteger(num)) return num.toString();
 return num.toFixed(2);
}

