 data: [company2.financials.marketCap / 1000000000, company2.financials.revenue / 1000000000, company2.financials.profitMargin * 100]
 }
 ]
 };
 } else if (chartType === 'usermetrics') {
 chartData = {
 labels: ['User Count', 'User Growth', 'Rating'],
 datasets: [
 {
