 data: [company2.customerMetrics.userCount / 1000000, company2.customerMetrics.userGrowth * 100, company2.customerMetrics.rating]
 }
 ]
 };
 }

 res.writeHead(200, {'Content-Type': 'application/json'});
 res.end(JSON.stringify({
 status: 'success',
 data: chartData
 }));
 } else {
