 const customerMetrics1 = company1.customerMetrics || {};
 const customerMetrics2 = company2.customerMetrics || {};

 const financialComparison = {
 marketCap: compareMetric(financials1.marketCap, financials2.marketCap, company1.id, company2.id),
 revenue: compareMetric(financials1.revenue, financials2.revenue, company1.id, company2.id),
 profitMargin: compareMetric(financials1.profitMargin, financials2.profitMargin, company1.id, company2.id),
 peRatio: compareMetric(financials1.peRatio, financials2.peRatio, company1.id, company2.id),
