 width1 = Math.abs(val1) / max * 100;
 width2 = Math.abs(val2) / max * 100;
 }
 }

 let winner = '';
 if (better) {
 winner = better === id1 ? 
 '<div class="winner-highlight">' + (value1 !== 'N/A' ? '✓' : '') + ' Company 1</div>' : 
 '<div class="winner-highlight">' + (value2 !== 'N/A' ? '✓' : '') + ' Company 2</div>';
