 <ul>${company.weaknesses.map(weakness => `<li>${weakness}</li>`).join('')}</ul>` : ''}
 ${company.competitors && company.competitors.length > 0 ? 
 `<h4>Main Competitors</h4>
 <ul>${company.competitors.map(competitor => `<li>${competitor}</li>`).join('')}</ul>` : ''}
 </div>
