 .compare-button { margin-top: 20px; }
 </style>
 </head>
 <body>
 <script>
 function toggleDescription(id) {
 const previewElem = document.getElementById('toggle-desc-' + id);
 const fullElem = document.getElementById('full-desc-' + id);

 if (fullElem.style.display === 'none') {
