 ? '<p>The comparison shows a <strong>tie</strong> between ' + companyNames[0] + ' and ' + companyNames[1] + '.</p>'
 : '<p>Based on the available metrics, <strong>' + overallWinner + '</strong> appears to be performing better overall.</p>'
 ) +
