 // Show overall winner
 const overallWinner = company1Wins > company2Wins ? companyNames[0] : (company2Wins > company1Wins ? companyNames[1] : 'Tie');
 document.getElementById('overall-winner').innerHTML = 
 '<h3>Overall Analysis</h3>' +
