 = {\n userBase: compareMetric(company1.customerMetrics.userCount, company2.customerMetrics.userCount, company1.id, company2.id),\n userGrowth: compareMetric(company1.customerMetrics.userGrowth, company2.customerMetrics.userGrowth, company1.id, company2.id),\n rating: compareMetric(company1.customerMetrics.rating, company2.customerMetrics.rating, company1.id, company2.id)\n };\n \n // Generate chart data\n const chartData = {\n finances: {\n labels: ['Market Cap', 'Revenue', 'Profit Margin'],\n datasets: [\n {\n company: company1.name,\n data: [\n company1.financials.marketCap ? company1.financials.marketCap / 1000000000 : 0,\n company1.financials.revenue ? company1.financials.revenue / 1000000000 : 0,\n company1.financials.profitMargin ? company1.financials.profitMargin * 100 : 0\n ]\n },\n {\n company: company2.name,\n data: [\n company2.financials.marketCap ? company2.financials.marketCap / 1000000000 : 0,\n company2.financials.revenue ? company2.financials.revenue / 1000000000 : 0,\n company2.financials.profitMargin ? company2.financials.profitMargin * 100 : 0\n ]\n }\n ]\n },\n userMetrics: {\n labels: ['User Count', 'User Growth', 'Rating'],\n datasets: [\n {\n company: company1.name,\n data: [\n company1.customerMetrics.userCount ? company1.customerMetrics.userCount / 1000000 : 0,\n company1.customerMetrics.userGrowth ? company1.customerMetrics.userGrowth * 100 : 0,\n company1.customerMetrics.rating || 0\n ]\n },\n {\n company: company2.name,\n data: [\n company2.customerMetrics.userCount ? company2.customerMetrics.userCount / 1000000 : 0,\n company2.customerMetrics.userGrowth ? company2.customerMetrics.userGrowth * 100 : 0,\n company2.customerMetrics.rating || 0\n ]\n }\n ]\n }\n };\n \n return {\n id,\n companies: [company1.id, company2.id],\n companyNames: [company1.name, company2.name],\n financialComparison,\n userMetricsComparison,\n chartData\n };\n}\n\n// Helper function to compare metrics\nfunction compareMetric(value1, value2, id1, id2) {\n // Handl