 if (company2Name) company2Data = await findOrCreateCompany(company2Name);

 const readmeContent = fs.existsSync(path.join(__dirname, '..', 'README.md')) ?
 fs.readFileSync(path.join(__dirname, '..', 'README.md'), 'utf8') :
 'README.md not found.';

 const htmlContent = `
