const http = require('http');
const https = require('https');
const fs = require('fs');
const path = require('path');
const url = require('url');

// Load configuration
const config = require('./config');

// Import Yahoo Finance API
const yahooFinance = require('yahoo-finance2').default;

// Static file serving
function serveStaticFile(filePath, res) {
 const fullPath = path.join(__dirname, '..', 'public', filePath);

 // Security check - prevent directory traversal
 if (!fullPath.startsWith(path.join(__dirname, '..', 'public'))) {
 res.writeHead(403, {'Content-Type': 'text/plain'});
 res.end('Forbidden');
 return;
 }

 fs.readFile(fullPath, (err, data) => {
 if (err) {
 res.writeHead(404, {'Content-Type': 'text/plain'});
 res.end('File not found');
 return;
 }

 // Set appropriate content type
 const ext = path.extname(filePath);
 const contentType = {
 '.html': 'text/html',
 '.js': 'application/javascript',
 '.css': 'text/css',
 '.json': 'application/json',
 '.png': 'image/png',
 '.jpg': 'image/jpeg',
 '.gif': 'image/gif',
 '.svg': 'image/svg+xml'
 }[ext] || 'text/plain';

 res.writeHead(200, {'Content-Type': contentType});
 res.end(data);
 });
}
let PORT = config.server.port; // Will be updated if a port is selected from fallbacks
const ALPHA_VANTAGE_API_KEY = config.api.alphaVantage.key;
const MISTRAL_API_KEY = config.api.mistral.key;
const USE_MISTRAL = config.api.mistral.enabled;
