```javascript
async function fetchDataFromGemini(companyName) {
 if (!USE_GEMINI || GEMINI_API_KEY === 'YOUR_GEMINI_API_KEY') {
 console.log('Gemini API key not set or integration disabled. Skipping Gemini data gathering.');
 return null;
 }

 console.log(`Fetching enhanced company data for ${companyName} from Gemini AI...`);
 console.log(`Using Gemini API for ${companyName}. This may take a few seconds...`);

 try {
 const prompt = `Analyze the company \"${companyName}\" and provide comprehensive business intelligence data in the following JSON format. Use your knowledge to provide accurate estimates and information:\n\n{\n \"description\": \"Comprehensive 2-3 sentence description of the company\'s business model and operations\",\n \"industry\": \"Primary industry/sector\",\n \"founded\": \"YYYY\",\n \"headquarters\": \"City, State/Country\",\n \"website\": \"Official website URL if known\",\n \"financials\": {\n \"stockSymbol\": \"Stock ticker symbol if publicly traded\",\n \"marketCap\": number_in_billions,\n \"revenue\": number_in_billions_annual,\n \"profitMargin\": decimal_percentage,\n \"peRatio\": number,\n \"eps\": number\n },\n \"strengths\": [\"List of 3-5 key competitive advantages\"],\n \"weaknesses\": [\"List of 2-3 main challenges or weaknesses\"],\n \"competitors\": [\"List of 3-5 main competitors\"],\n \"customerMetrics\": {\n \"userCount\": number_in_millions,\n \"userGrowth\": decimal_growth_rate,\n \"rating\": number_out_of_5\n },\n \"products\": [\n {\"name\": \"Product name\", \"category\": \"Product category\"}\n ],\n \"recentNews\": \"Brief summary of recent significant developments or news\",\n \"marketPosition\": \"Brief description of market position and competitive standing\"\n}\n\nProvide realistic estimates based on publicly available information and industry knowledge. For financial data, use approximate values in billions for market cap and revenue.`;

 const response = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key=${GEMINI_API_KEY}`, {
 method: 'POST',
 headers: {
 'Content-Type': 'application/json'
 },
 body: JSON.stringify({
 contents: [{
 parts: [{
 text: prompt
 }]
 }],
 generationConfig: {
 temperature: 0.2,
 topK: 1,
 topP: 1,
 maxOutputTokens: 2048
 }
 })
 });

 if (!response.ok) {
 const errorText = await response.text();
 console.error(`Gemini API error: ${response.status} ${response.statusText}`, errorText);\
 return null;
 }

 const data = await response.json();

 if (!data.candidates || !data.candidates[0] || !data.candidates[0].content || !data.candidates[0].content.parts) {
 console.error('Unexpected Gemini API response format:', data);
 return null;
 }

 let responseText = data.candidates[0].content.parts[0].text;
 console.log(`Received response from Gemini for ${companyName}`);

 // Strip markdown JSON block if present
 if (responseText.startsWith("```json")) {
 responseText = responseText.substring(7, responseText.length - 3).trim();
 } else if (responseText.startsWith("```")) {
 responseText = responseText.substring(3, responseText.length - 3).trim();
 }

 let result;
 try {
 result = JSON.parse(responseText);
 console.log(`Successfully processed Gemini data for ${companyName}`);
 result._source = 'gemini';
 result._timestamp = new Date().toISOString();
 return result;
 } catch (e) {
 console.error('Failed to parse Gemini response as JSON:', e);
 console.log('Raw content for Gemini (first 500 chars):', responseText.substring(0, 500) + '...');
 return null;
 }

 } catch (error) {
 console.error('Error fetching data from Gemini:', error);
 return null;
 }
}
```

