ngth === 0))) {\n target[field] = value;\n companyData.dataSourceDetails.push({ field, source: sourceName, value: typeof value === 'string' && value.length > 100 ? value.substring(0,100)+'...' : value });\n return true;\n }\n return false;\n }\n\n function mergeFinancialField(field, value, sourceName) {\n return mergeField(companyData.financials, field, value, sourceName);\n }\n \n function mergeCustomerMetricField(field, value, sourceName) {\n return mergeField(companyData.customerMetrics, field, value, sourceName);\n }\n\n // --- Symbol Resolution ---\n let stockSymbol = null;\n const popularEntry = popularCompanies.find(pc => pc.name.toLowerCase() === normalizedCompanyName);\n\n if (popularEntry && popularEntry.symbol) {\n stockSymbol = popularEntry.symbol;\n console.log(`✓ Using pre-vetted symbol \"${stockSymbol}\" for \"${companyName}\" from popular list.`);\n companyData.financials.stockSymbol = stockSymbol; // Set it early\n } else {\n console.log(`~ \"${companyName}\" not in popular list or symbol missing, attempting Alpha Vantage symbol search...`);\n stockSymbol = await searchStockSymbol(companyName); \n if (stockSymbol) {\n companyData.financials.stockSymbol = stockSymbol; // Set it if found\n }\n }\n \n // --- Data Fetching Hierarchy ---\n\n // 1. Yahoo Finance (Primary for Financials)\n if (stockSymbol) {\n const yahooData = await fetchStockDataYahoo(stockSymbol);\n if (yahooData) {\n console.log(`✓ Data obtained from Yahoo Finance for ${stockSymbol}`);\n mergeFinancialField('stockPrice', yahooData.stockPrice, 'Yahoo Finance');\n mergeFinancialField('marketCap', yahooData.marketCap, 'Yahoo Finance');\n mergeFinancialField('revenue', yahooData.revenue, 'Yahoo Finance');\n mergeFinancialField('profitMargin', yahooData.profitMargin, 'Yahoo Finance');\n mergeFinancialField('peRatio', yahooData.peRatio, 'Yahoo Finance');\n mergeFinancialField('eps', yahooData.eps, 'Yahoo Finance');\n if(companyData.dataSource === 'fallback') companyData.dataSource = 'Yahoo Finance';\n } else {\n console.log(`✗ Yahoo Finance fetch failed or returned no data for ${stockSymbol}.`);\n }\n } else {\n console.log(`✗ No stock symbol for \"${companyName}\", Yahoo Finance skipped.`);\n }\n\n // 2. CompaniesMarketCap (Fallback for Market Cap, Price, Symbol if still needed)\n if (hasEmptyFinancialFields(companyData.financials, ['marketCap', 'stockPrice']) || !companyData.financials.stockSymbol) {\n const marketCapData = await scrapeCompanyFromMarketCap(companyData.name); // Use original name for scraping\n if (marketCapData && marketCapData.financials) {\n console.log(`✓ Data obtained from CompaniesMarketCap for ${companyData.name}`);\n mergeFinancialField('stockSymbol', marketCapData.financials.stockSymbol, 'CompaniesMarketCap');\n // Re-assign stockSymbol if CompaniesMarketCap found a better one and Yahoo didn't\n if (marketCapData.financials.stockSymbol && !stockSymbol) {\n stockSymbol = marketCapData.financials.stockSymbol; \n companyData.financials.stockSymbol = stockSymbol;\n }\n mergeFinancialField('marketCap', marketCapData.financials.marketCap, 'CompaniesMarketCap');\n mergeFinancialField('stockPrice', marketCapData.financials.stockPrice, 'CompaniesMarketCap');\n if(companyData.dataSource === 'fallback') companyData.dataSource = 'CompaniesMarketCap';\n } else {\n console.log(`✗ CompaniesMarketCap fetch failed or returned no data for ${companyData.name}.`);\n }\n }\n \n const needsMoreCompanyInfo = () => !companyData.description || !companyData.industry || !companyData.founded || !companyData.headquarters || !companyData.website;\n\n // 3. Gemini AI (Comprehensive Business Data & Fallback Financials)\n if (USE_GEMINI && (hasEmptyFinancialFields(companyData.financials) || needsMoreCompanyInfo() || companyData.strengths.length === 0)) {\n const geminiData = await fetchDataFromGemini(companyData.name);\n if (geminiData) {\n console.log(`✓ Data obtained from Gemini AI for ${companyData.name}`);\n mergeField(companyData, 'description', geminiData.description, 'Gemini AI');\n mergeField(companyData, 'industry', geminiData.industry, 'Gemini AI');\n mergeField(companyData, 'founded', geminiData.founded ? parseInt(geminiData.founded) : null, 'Gemini AI');\n mergeField(companyData, 'headquarters', geminiData.headquarters, 'Gemini AI');\n mergeField(companyData, 'website', geminiData.website, 'Gemini AI');\n mergeField(companyData, 'strengths', geminiData.strengths, 'Gemini AI');\n mergeField(companyData, 'weaknesses', geminiData.weaknesses, 'Gemini AI');\n mergeField(companyData, 'competitors', geminiData.competitors, 'Gemini AI');\n mergeField(companyData, 'recentNews', geminiData.recentNews, 'Gemini AI');\n mergeField(companyData, 'marketPosition', geminiData.marketPosition, 'Gemini AI');\n\n if (geminiData.financials) {\n const convertB = (v) => v !== null && v !== undefined ? v * 1e9 : null;\n mergeFinancialField('stockSymbol', geminiData.financials.stockSymbol, 'Gemini AI (Estimate)');\n mergeFinancialField('marketCap', convertB(geminiData.financials.marketCap), 'Gemini AI (Estimate)');\n mergeFinancialField('revenue', convertB(geminiData.financials.revenue), 'Gemini AI (Estimate)');\n mergeFinancialField('profitMargin', geminiData.financials.profitMargin, 'Gemini AI (Estimate)');\n mergeFinancialField('peRatio', geminiData.financials.peRatio, 'Gemini AI (Estimate)');\n mergeFinancialField('eps', geminiData.financials.eps, 'Gemini AI (Estimate)');\n }\n if (geminiData.customerMetrics) {\n const convertM = (v) => v !== null && v !== undefined ? v * 1e6 : null;\n mergeCustomerMetricField('userCount', convertM(geminiData.customerMetrics.userCount), 'Gemini AI (Estimate)');\n mergeCustomerMetricField('userGrowth', geminiData.customerMetrics.userGrowth, 'Gemini AI (Estimate)');\n mergeCustomerMetricField('rating', geminiData.customerMetrics.rating, 'Gemini AI (Estimate)');\n }\n if (geminiData.products) mergeField(companyData, 'products', geminiData.products, 'Gemini AI');\n if(companyData.dataSource === 'fal